import subprocess,base64,zlib,json,os,re,sys
BIN='/workspace/executable'
def enc(s):
    if isinstance(s,(dict,list)): s=json.dumps(s,separators=(',',':'))
    if isinstance(s,str): s=s.encode()
    return base64.urlsafe_b64encode(zlib.compress(s,9)).decode()
def dec(v):
    s=v.replace('_','/').replace('-','+'); s+='='*(-len(s)%4)
    return zlib.decompress(base64.urlsafe_b64decode(s)).decode()
def run(args,cwd,env=None,merge=None):
    e=dict(os.environ)
    if env is not None: e.update(env)
    if merge is not None:
        for k in merge: e.pop(k,None)
    p=subprocess.run([BIN]+args,capture_output=True,cwd=cwd,env=e)
    return p
def show(cwd,args,env=None,label=''):
    p=run(args,cwd,env)
    print("### %s %s %s"%(label,cwd,args))
    if p.stderr: print("  STDERR:",p.stderr.decode('utf8','replace').replace('\x1b','\\e'))
    print("  STDOUT:",p.stdout.decode('utf8','replace'))
    print("  RC:",p.returncode)
    return p
PY
