import sys,os,re,json,base64,zlib,subprocess,time,shutil
BIN='/workspace/executable'
def enc(s):
    if isinstance(s,(dict,list)): s=json.dumps(s,separators=(',',':'))
    if isinstance(s,str): s=s.encode()
    return base64.urlsafe_b64encode(zlib.compress(s,9)).decode()
def dec(v):
    s=v.replace('_','/').replace('-','+'); s+='='*(-len(s)%4)
    return zlib.decompress(base64.urlsafe_b64decode(s)).decode()
def bash_unesc(v):
    out=[];i=0
    while i<len(v):
        if v[i]=='\\' and i+1<len(v):
            c=v[i+1]
            mp={'n':'\n','t':'\t','r':'\r','\\':'\\',"'":"'"}
            if c=='x' and i+3<len(v):
                out.append(chr(int(v[i+2:i+4],16))); i+=4; continue
            out.append(mp.get(c,c)); i+=2; continue
        out.append(v[i]); i+=1
    return ''.join(out)
def parse_exports(out):
    res={}
    for m in re.finditer(r"export ([A-Za-z_][A-Za-z0-9_]*)=(\$?'((?:[^']|\\')*)'|[^;]*);", out):
        k=m.group(1); v=m.group(2)
        if v.startswith("$'"): v=bash_unesc(v[2:-1])
        elif v.startswith("'"): v=v[1:-1]
        res[k]=v
    for m in re.finditer(r"unset ([A-Za-z_][A-Za-z0-9_]*);", out):
        res.pop(m.group(1),None)
    return res
class Hook:
    def __init__(self, cwd, baseenv=None):
        self.cwd=cwd
        self.env=dict(baseenv or {})
    def hook(self, label='', show=True):
        e=dict(os.environ); e.update(self.env)
        e.pop('DIRENV_LOG_FORMAT',None)
        p=subprocess.run([BIN,'export','bash'],capture_output=True,cwd=self.cwd,env=e)
        log=p.stderr.decode('utf8','replace').replace('\x1b','\\e').strip()
        out=p.stdout.decode('utf8','replace')
        self.env.update(parse_exports(out))
        if show:
            print("%-24s log=%r"%(label,log))
            print("%-24s exports=%r"%(label, sorted(re.findall(r"export ([A-Za-z_][A-Za-z0-9_]*)=|unset (\w+);", out))))
        return p
PY
