package main

import (
	"fmt"
	"os"
	"regexp"
	"strings"
)

// ANSI colors used for the log output
const (
	colorRed   = "\033[31m"
	colorReset = "\033[0m"
)

// Logger is the interface used to log messages. It is set to stderr by
// default, but it can be redirected when needed (eg: when running inside a
// .envrc evaluation context).
type Logger func(msg string)

// LogStatus logs a message to stderr with the standard direnv format.
func LogStatus(msg string) {
	logger := config.LogFormatFunc()
	logger(msg)
}

// LogError logs an error to stderr with the standard direnv format.
func LogError(msg string) {
	logger := config.LogFormatFunc()
	logger(msg)
}

var logFilter = regexp.MustCompile("")

// DefaultLogStatus is the standard "direnv: " prefixed logger.
func DefaultLogStatus(msg string) {
	if config.LogFilter != "" {
		re, err := regexp.Compile(config.LogFilter)
		if err == nil && re.MatchString(msg) {
			return
		}
	}
	fmt.Fprintln(os.Stderr, colorReset+"direnv: "+msg)
}

// DefaultLogError is the standard "direnv: error " prefixed logger.
func DefaultLogError(msg string) {
	if config.LogFilter != "" {
		re, err := regexp.Compile(config.LogFilter)
		if err == nil && re.MatchString(msg) {
			return
		}
