package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// Config holds the direnv configuration
type Config struct {
	SelfPath  string
	Loaded    bool
	BashPath  string
	DataDir   string
	ConfigDir string

	DisableStdin  bool
	LoadDotenv    bool
	StrictEnv     bool
	WarnTimeout   time.Duration
	HideEnvDiff   bool
	LogFormat     string
	LogFilter     string

	WhitelistPrefix []string
	WhitelistExact  map[string]bool
}

var config = &Config{
	BashPath:        "/usr/bin/bash",
	WarnTimeout:     5 * time.Second,
	WhitelistExact:  map[string]bool{},
}

// XDGConfigHome returns the value of $XDG_CONFIG_HOME
func XDGConfigHome() string {
	if v := os.Getenv("XDG_CONFIG_HOME"); v != "" {
		return v
	}
	return filepath.Join(os.Getenv("HOME"), ".config")
}

// XDGDataHome returns the value of $XDG_DATA_HOME
func XDGDataHome() string {
	if v := os.Getenv("XDG_DATA_HOME"); v != "" {
		return v
	}
	return filepath.Join(os.Getenv("HOME"), ".local", "share")
}

// XDGCacheHome returns the value of $XDG_CACHE_HOME
func XDGCacheHome() string {
	if v := os.Getenv("XDG_CACHE_HOME"); v != "" {
		return v
	}
	return filepath.Join(os.Getenv("HOME"), ".cache")
}

// ExpandHome expands a leading ~ into the user's home directory
func ExpandHome(path string) string {
	if strings.HasPrefix(path, "~") {
		if len(path) == 1 {
			return os.Getenv("HOME")
		}
		if path[1] == '/' {
			return filepath.Join(os.Getenv("HOME"), path[2:])
		}
	}
	return path
}

// LoadConfig loads the direnv configuration
func LoadConfig() error {
	selfPath, err := os.Executable()
	if err != nil {
		return err
	}
	selfPath, err = filepath.Abs(selfPath)
	if err != nil {
		return err
	}
	config.SelfPath = selfPath

	if v := os.Getenv("DIRENV_CONFIG"); v != "" {
		config.ConfigDir = v
	} else {
		config.ConfigDir = filepath.Join(XDGConfigHome(), "direnv")
	}
	config.DataDir = filepath.Join(XDGDataHome(), "direnv")

	// default bash path
	if p, err := execLookPath("bash"); err == nil {
		config.BashPath = p
	} else {
		return fmt.Errorf("can't find bash: %s", err)
	}

	configPath := filepath.Join(config.ConfigDir, "direnv.toml")
	st, err := os.Stat(configPath)
	if err != nil || st.IsDir() {
		// No config file: keep the defaults
		return nil
	}
	data, err := os.ReadFile(configPath)
	if err != nil {
		return err
	}
	tree, err := ParseTOML(string(data))
	if err != nil {
		return fmt.Errorf("LoadConfig() failed to parse %s: %s", configPath, err)
	}
	config.Loaded = true
	config.ApplyTOML(tree)
	return nil
}

// ApplyTOML applies a parsed TOML document to the configuration
func (c *Config) ApplyTOML(tree *TOMLValue) {
	if tree == nil {
		return
	}
	g := tree.Table("global")
	if g != nil {
		if v := g.String("bash_path"); v != "" {
			c.BashPath = v
		}
		if v, ok := g.Bool("disable_stdin"); ok {
			c.DisableStdin = v
		}
		if v, ok := g.Bool("load_dotenv"); ok {
			c.LoadDotenv = v
		}
		if v, ok := g.Bool("strict_env"); ok {
			c.StrictEnv = v
		}
		if v := g.String("warn_timeout"); v != "" {
			if d, err := time.ParseDuration(v); err == nil {
				c.WarnTimeout = d
			}
		}
		if v, ok := g.Bool("hide_env_diff"); ok {
			c.HideEnvDiff = v
		}
		if v, ok := g.StringOk("log_format"); ok {
			c.LogFormat = v
		}
		if v, ok := g.StringOk("log_filter"); ok {
			c.LogFilter = v
		}
	}
	w := tree.Table("whitelist")
	if w != nil {
		c.WhitelistPrefix = w.StringArray("prefix")
		exact := map[string]bool{}
		for _, v := range w.StringArray("exact") {
			exact[ExpandHome(v)] = true
		}
		c.WhitelistExact = exact
	}
}
GOEOF
echo ok"}

