{"command": "cd /workspace/src && cat > toml.go <<'GOEOF'
package main

import (
	"fmt"
	"strings"
)

// TOMLValue is a parsed TOML document. Values are stored as nested maps.
type TOMLValue struct {
	val interface{}
}

// ParseTOML parses a TOML document into a TOMLValue tree.
func ParseTOML(src string) (*TOMLValue, error) {
	p := &tomlParser{src: src}
	root := map[string]interface{}{}
	cur := root
	curKey := ""
	var curKeyPath []string
	lines := strings.Split(src, "\n")
	line := 0
	for i := 0; i < len(lines); i++ {
		line = i + 1
		s := strings.TrimSpace(lines[i])
		// strip comments (naive, doesn't handle # inside strings)
		for len(s) > 0 {
			if s[0] == '#' {
				s = ""
				break
			}
			break
		}
		// handle full-line comments only; inline comments are handled by the
		// value parser
		if s == "" {
			continue
		}
		if s[0] == '[' {
			// table or array of tables
			isArray := false
			rest := s[1:]
			if strings.HasPrefix(rest, "[") {
				isArray = true
				rest = rest[1:]
			}
			idx := strings.Index(rest, "]")
			if idx < 0 {
				// find the end
				if isArray {
					idx = strings.Index(rest, "]")
				}
				if idx < 0 {
					if isArray {
						idx = -2
					} else {
						idx = -2
					}
				}
			}
			name := ""
			closed := true
			if idx < 0 {
				closed = false
				name = strings.TrimSpace(rest)
			} else {
				name = strings.TrimSpace(rest[:idx])
			}
			// handle [[...]]
			if isArray {
				if !strings.HasPrefix(name, "[") {
					return nil, fmt.Errorf("toml: line %d: expected value but found '%s' instead", line, name)
				}
			}
			if !closed {
				if isArray {
					if strings.Contains(s, "]]") {
						// ok
					} else {
						return nil, fmt.Errorf("toml: line %d: expected '.' or ']' to end table name, but got '\\n' instead", line)
					}
				} else {
					return nil, fmt.Errorf("toml: line %d: expected '.' or ']' to end table name, but got '\\n' instead", line)
				}
			}
			if name == "" {
				return nil, fmt.Errorf("toml: line %d: unexpected end of table name (table names cannot be empty)", line)
			}
			if isArray {
				parts := strings.Split(name, ".")
				parent := root
				for _, part := range parts {
					part = strings.Trim(part, `"'`)
					v, ok := parent[part]
					if !ok {
						nv := []map[string]interface{}{}
						parent[part] = nv
						v = nv
					}
					arr, ok := v.([]map[string]interface{})
					if !ok {
						return nil, fmt.Errorf("toml: line %d (last key \"%s\"): type mismatch for %s: expected table but found %s", line, strings.Join(parts, "."), tomlTypeName(line, parts), "[]map[string]any")
					}
					parent = arr[len(arr)-1]
					curKeyPath = append(curKeyPath, part)
				}
				cur = parent
				curKey = strings.Join(parts, ".")
				continue
			}
			parts := strings.Split(name, ".")
			parent := root
			for _, part := range parts {
				part = strings.Trim(part, `"'`)
				v, ok := parent[part]
				if !ok {
					nv := map[string]interface{}{}
					parent[part] = nv
					v = nv
				}
				m, ok := v.(map[string]interface{})
				if !ok {
					return nil, fmt.Errorf("toml: line %d: type mismatch: expected table but found other", line)
				}
				parent = m
			}
			cur = parent
			curKey = name
			curKeyPath = parts
			continue
		}
		// key = value
		eq := strings.Index(s, "=")
		if eq < 0 {
			if curKey == "" {
				return nil, fmt.Errorf("toml: line %d: expected '.' or '=', but got '\\n' instead", line)
			}
			return nil, fmt.Errorf("toml: line %d (last key \"%s\"): expected '.' or '=', but got '\\n' instead", line, curKey)
		}
		key := strings.TrimSpace(s[:eq])
		key = strings.Trim(key, `"'`)
		if key == "" {
			return nil, fmt.Errorf("toml: line %d: unexpected end of table name (table names cannot be empty)", line)
		}
		rest := strings.TrimSpace(s[eq+1:])
		val, consumed, err := tomlParseValue(rest, line, curKey)
		if err != nil {
			return nil, err
		}
		_ = consumed
		fullKey := curKey
		if fullKey != "" {
			fullKey = fullKey + "." + key
		} else {
			fullKey = key
		}
		if _, exists := cur[key]; exists {
			return nil, fmt.Errorf("toml: line %d (last key \"%s\"): Key '%s' has already been defined.", line, fullKey, fullKey)
		}
		cur[key] = val
		curKey = fullKey
	}
	return &TOMLValue{val: root}, nil
}

func tomlTypeName(line int, parts []string) string {
	return "cmd.toml" + strings.Title(strings.Join(parts, ""))
}

// tomlParseValue parses a TOML value from the beginning of s.
func tomlParseValue(s string, line int, lastKey string) (interface{}, int, error) {
	s = strings.TrimLeft(s, " \t")
	if s == "" {
		if lastKey == "" {
			return nil, 0, fmt.Errorf("toml: line %d: expected value but found '\\n' instead", line)
		}
		return nil, 0, fmt.Errorf("toml: line %d (last key \"%s\"): expected value but found '\\n' instead", line, lastKey)
	}
	switch s[0] {
	case '"':
		v, n, err := tomlParseBasicString(s, line, lastKey)
		return v, n, err
	case '\'':
		v, n, err := tomlParseLiteralString(s, line, lastKey)
		return v, n, err
	case '[':
		return tomlParseArray(s, line, lastKey)
	case '{':
		return tomlParseInlineTable(s, line, lastKey)
	}
	// bare value: take up to the comment or end
	end := len(s)
	for i := 0; i < len(s); i++ {
		if s[i] == '#' {
			end = i
			break
		}
	}
	raw := strings.TrimSpace(s[:end])
	if raw == "" {
		if lastKey == "" {
			return nil, 0, fmt.Errorf("toml: line %d: expected value but found '\\n' instead", line)
		}
		return nil, 0, fmt.Errorf("toml: line %d (last key \"%s\"): expected value but found '\\n' instead", line, lastKey)
	}
	switch raw {
	case "true":
		return true, len(s), nil
	case "false":
		return false, len(s), nil
	}
	// numbers
	if tomlIsNumber(raw) {
		return tomlParseNumber(raw), len(s), nil
	}
	if lastKey == "" {
		return nil, 0, fmt.Errorf("toml: line %d: expected value but found \"%s\" instead", line, raw)
	}
	return nil, 0, fmt.Errorf("toml: line %d (last key \"%s\"): expected value but found \"%s\" instead", line, lastKey, raw)
