func tomlIsNumber(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= '0' && c <= '9':
		case c == '+' || c == '-' || c == '.' || c == '_' || c == 'e' || c == 'E':
		case c == 'x' || c == 'o' || c == 'b':
		case c == 'a' || c == 'A' || c == 'c' || c == 'd' || c == 'f' || c == 'F' || c == 'i' || c == 'n':
		case c == ':':
		default:
			return false
		}
	}
	return true
