func tomlParseNumber(s string) interface{} {
	s = strings.ReplaceAll(s, "_", "")
	if strings.Contains(s, ".") || strings.Contains(s, "e") || strings.Contains(s, "E") {
		var f float64
		fmt.Sscanf(s, "%g", &f)
		return f
	}
	var i int64
	fmt.Sscanf(s, "%d", &i)
	return i
}

func tomlParseBasicString(s string, line int, lastKey string) (interface{}, int, error) {
	// multi-line?
	if strings.HasPrefix(s, `"""`) {
		idx := strings.Index(s[3:], `"""`)
		if idx < 0 {
			return nil, 0, fmt.Errorf("toml: line %d: strings cannot contain newlines", line)
		}
		body := s[3 : 3+idx]
		return tomlUnescape(body), 3 + idx + 3, nil
	}
	for i := 1; i < len(s); i++ {
		if s[i] == '\\' {
			i++
			continue
		}
		if s[i] == '"' {
			return tomlUnescape(s[1:i]), i + 1, nil
		}
		if s[i] == '\n' {
			if lastKey == "" {
				return nil, 0, fmt.Errorf("toml: line %d: strings cannot contain newlines", line)
			}
			return nil, 0, fmt.Errorf("toml: line %d (last key \"%s\"): strings cannot contain newlines", line, lastKey)
		}
	}
	return nil, 0, fmt.Errorf("toml: line %d: strings cannot contain newlines", line)
}

func tomlParseLiteralString(s string, line int, lastKey string) (interface{}, int, error) {
	for i := 1; i < len(s); i++ {
		if s[i] == '\'' {
			return s[1:i], i + 1, nil
		}
		if s[i] == '\n' {
			return nil, 0, fmt.Errorf("toml: line %d: strings cannot contain newlines", line)
		}
	}
	return nil, 0, fmt.Errorf("toml: line %d: strings cannot contain newlines", line)
}

func tomlParseArray(s string, line int, lastKey string) (interface{}, int, error) {
	res := []interface{}{}
	i := 1
	for i < len(s) {
		// skip whitespace and comments and newlines
