			i++
		}
		if i < len(s) && s[i] == '#' {
			for i < len(s) && s[i] != '\n' {
				i++
			}
			continue
		}
		if i < len(s) && s[i] == ']' {
			return res, i + 1, nil
		}
		v, n, err := tomlParseValue(s[i:], line, lastKey)
		if err != nil {
			return nil, 0, err
		}
		res = append(res, v)
		i += n
		for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\r') {
			i++
		}
		if i < len(s) && s[i] == ',' {
			i++
			continue
		}
		if i < len(s) && s[i] == ']' {
			return res, i + 1, nil
		}
		if i >= len(s) {
			break
		}
	}
	return res, len(s), nil
}

func tomlParseInlineTable(s string, line int, lastKey string) (interface{}, int, error) {
	res := map[string]interface{}{}
	i := 1
	for i < len(s) {
		for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		if i < len(s) && s[i] == '}' {
			return res, i + 1, nil
		}
		eq := strings.Index(s[i:], "=")
		if eq < 0 {
			break
		}
		key := strings.TrimSpace(s[i : i+eq])
		key = strings.Trim(key, `"'`)
		v, n, err := tomlParseValue(s[i+eq+1:], line, lastKey)
		if err != nil {
			return nil, 0, err
		}
		res[key] = v
		i += eq + 1 + n
		for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
			i++
		}
		if i < len(s) && s[i] == ',' {
			i++
			continue
		}
	}
	return res, len(s), nil
}

func tomlUnescape(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] != '\\' || i+1 >= len(s) {
			b.WriteByte(s[i])
			continue
		}
		i++
		switch s[i] {
		case 'n':
			b.WriteByte('\n')
		case 't':
			b.WriteByte('\t')
		case 'r':
			b.WriteByte('\r')
		case '"':
			b.WriteByte('"')
		case '\\':
			b.WriteByte('\\')
		case 'b':
			b.WriteByte(8)
		case 'f':
			b.WriteByte(12)
		case 'u', 'U':
			n := 4
			if s[i] == 'U' {
				n = 8
			}
			if i+n < len(s) {
				var r rune
				fmt.Sscanf(s[i+1:i+1+n], "%x", &r)
				b.WriteRune(r)
				i += n
			}
		default:
			b.WriteByte('\\')
			b.WriteByte(s[i])
		}
	}
	return b.String()
}

// Table returns a sub-table
func (t *TOMLValue) Table(name string) *TOMLValue {
	if t == nil {
		return nil
	}
	m, ok := t.val.(map[string]interface{})
	if !ok {
		return nil
	}
	v, ok := m[name]
	if !ok {
		return nil
	}
	return &TOMLValue{val: v}
}

func (t *TOMLValue) get(name string) (interface{}, bool) {
	if t == nil {
		return nil, false
	}
	m, ok := t.val.(map[string]interface{})
	if !ok {
		return nil, false
	}
	v, ok := m[name]
	return v, ok
}

// String returns a string value
func (t *TOMLValue) String(name string) string {
	v, ok := t.get(name)
	if !ok {
		return ""
	}
	s, _ := v.(string)
	return s
}

// StringOk returns a string value and whether it was present
func (t *TOMLValue) StringOk(name string) (string, bool) {
	v, ok := t.get(name)
	if !ok {
		return "", false
	}
	s, _ := v.(string)
	return s, true
}

// Bool returns a boolean value
func (t *TOMLValue) Bool(name string) (bool, bool) {
	v, ok := t.get(name)
	if !ok {
		return false, false
	}
	b, _ := v.(bool)
	return b, true
}

// StringArray returns an array of strings
func (t *TOMLValue) StringArray(name string) []string {
	v, ok := t.get(name)
	if !ok {
		return nil
	}
	arr, ok := v.([]interface{})
	if !ok {
		return nil
	}
	res := []string{}
	for _, x := range arr {
		s, _ := x.(string)
		res = append(res, s)
	}
	return res
}
