		rest := strings.TrimSpace(s[eq+1:])
		val, consumed, err := tomlParseValue(rest, line, curKey)
		if err != nil {
			return nil, err
		}
		_ = consumed
		fullKey := curKey
		if fullKey != "" {
			fullKey = fullKey + "." + key
		} else {
