{"command": "cd /workspace/src && cat > env.go <<'GOEOF'
package main

import (
	"compress/zlib"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
)

// Env is a map of environment variables
type Env map[string]string

// Keys returns the sorted keys of the environment
func (e Env) Keys() []string {
	keys := make([]string, 0, len(e))
	for k := range e {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// Marshal serializes the environment to a compact JSON string
func (e Env) Marshal() ([]byte, error) {
	return json.Marshal(map[string]string(e))
}

// UnmarshalEnv parses a JSON environment
func UnmarshalEnv(data []byte) (Env, error) {
	var e Env
	if err := json.Unmarshal(data, &e); err != nil {
		return nil, err
	}
	if e == nil {
		e = Env{}
	}
	return e, nil
}

// MarshalDump encodes the environment in the internal dump format: zlib
// compressed JSON encoded with unpadded base64url.
func (e Env) MarshalDump() (string, error) {
	data, err := e.Marshal()
	if err != nil {
		return "", err
	}
	return encodeDump(data)
}

func encodeDump(data []byte) (string, error) {
	var buf strings.Builder
	w := zlib.NewWriter(&dumpWriter{b: &buf})
	if _, err := w.Write(data); err != nil {
		return "", err
	}
	if err := w.Close(); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString([]byte(buf.String())), nil
}

// decodeDump decodes a dump string (base64url encoded, zlib compressed)
func decodeDump(dump string) ([]byte, error) {
	data, err := base64.URLEncoding.DecodeString(dump)
	if err != nil {
		return nil, fmt.Errorf("unmarshal() base64 decoding: %s", err)
	}
	zr, err := zlib.NewReader(strings.NewReader(string(data)))
	if err != nil {
		return nil, fmt.Errorf("unmarshal() zlib decoding: %s", err)
	}
	defer zr.Close()
	out, err := io.ReadAll(zr)
	if err != nil {
		return nil, fmt.Errorf("unmarshal() zlib decoding: %s", err)
	}
	return out, nil
}

type dumpWriter struct{ b *strings.Builder }

func (w *dumpWriter) Write(p []byte) (int, error) { return w.b.WriteString(string(p)) }

// Diff is the difference between two environments
type Diff struct {
	p Env // previous
	n Env // new
}

// MarshalDump encodes the diff in the internal dump format
func (d Diff) MarshalDump() (string, error) {
	data, err := json.Marshal(struct {
		P map[string]string `json:"p"`
		N map[string]string `json:"n"`
	}{P: map[string]string(d.p), N: map[string]string(d.n)})
	if err != nil {
		return "", err
	}
	var buf strings.Builder
	w := zlib.NewWriter(&dumpWriter{b: &buf})
	if _, err := w.Write(data); err != nil {
		return "", err
	}
	if err := w.Close(); err != nil {
		return "", err
	}
	return base64.URLEncoding.EncodeToString([]byte(buf.String())), nil
}

// UnmarshalDiff parses a diff dump
func UnmarshalDiff(dump string) (Diff, error) {
	data, err := decodeDump(dump)
	if err != nil {
		return Diff{}, err
	}
	var d Diff
	if err := json.Unmarshal(data, &d); err != nil {
		return Diff{}, err
	}
	if d.p == nil {
		d.p = Env{}
	}
	if d.n == nil {
		d.n = Env{}
	}
	return d, nil
}

// Revert returns the inverse diff, which undoes the changes of d
func (d Diff) Revert() Diff {
	p := Env{}
	n := Env{}
	for k, v := range d.p {
		n[k] = v
	}
	for k := range d.n {
		if _, ok := d.p[k]; !ok {
			p[k] = ""
		}
	}
	return Diff{p: p, n: n}
}

// Log returns the log message describing the diff
func (d Diff) Log() string {
	var changes []string
	for k, v := range d.n {
		if isPrivateEnvKey(k) {
			continue
		}
		if pv, ok := d.p[k]; !ok {
			changes = append(changes, "+"+k)
		} else if pv != v {
			changes = append(changes, "~"+k)
		}
	}
	for k := range d.p {
		if isPrivateEnvKey(k) {
			continue
		}
		if _, ok := d.n[k]; !ok {
			changes = append(changes, "-"+k)
		}
	}
	sort.Strings(changes)
	return "export " + strings.Join(changes, " ")
}

// isPrivateEnvKey returns true for environment keys that direnv manages and
// which should not show up in the environment diff.
func isPrivateEnvKey(k string) bool {
	switch k {
	case "DIRENV_DIR", "DIRENV_FILE", "DIRENV_WATCHES", "DIRENV_DIFF",
		"DIRENV_IN_ENVRC", "DIRENV_DUMP_FILE_PATH":
		return true
	}
	return false
}

// ignoredEnvKeys are keys that never take part in the environment diff
var ignoredEnvKeys = map[string]bool{
	"SHLVL":   true,
	"PWD":     true,
	"OLDPWD":  true,
	"_":       true,
	"DIRENV_DIFF": true,
}

// DiffOf computes the diff between two environments
func DiffOf(prev, next Env) Diff {
	p := Env{}
	n := Env{}
	for k, v := range next {
		if ignoredEnvKeys[k] {
			continue
		}
		if pv, ok := prev[k]; !ok {
			n[k] = v
		} else if pv != v {
			p[k] = pv
			n[k] = v
		}
	}
	for k, v := range prev {
		if ignoredEnvKeys[k] {
			continue
		}
		if _, ok := next[k]; !ok {
			p[k] = v
		}
	}
	return Diff{p: p, n: n}
}

// LoadEnvDump reads the environment from a dump string
func LoadEnvDump(dump string) (Env, error) {
	data, err := decodeDump(dump)
	if err != nil {
		return nil, err
	}
	return UnmarshalEnv(data)
}

// loadPrevEnv returns the previous environment, taken from the current
// process environment overlaid with the values of the stored diff.
func loadPrevEnv(prev *Diff) Env {
	env := Env{}
	for _, kv := range os.Environ() {
		i := strings.Index(kv, "=")
		if i < 0 {
			continue
		}
		env[kv[:i]] = kv[i+1:]
	}
	if prev != nil {
		for k, v := range prev.p {
			env[k] = v
		}
	}
	return env
}

// currentProcessEnv returns a copy of the current process environment
func currentProcessEnv() Env {
	env := Env{}
	for _, kv := range os.Environ() {
		i := strings.Index(kv, "=")
		if i < 0 {
			continue
		}
		env[kv[:i]] = kv[i+1:]
	}
	return env
}
GOEOF
echo ok"}

