// Watch is a single watched path
type Watch struct {
	Path    string `json:"path"`
	ModTime int64  `json:"modtime"`
	Exists  bool   `json:"exists"`
}

// Watches is a list of watched paths
type Watches []Watch

// MarshalDump encodes the watches in the internal dump format
func (w Watches) MarshalDump() (string, error) {
	data, err := json.Marshal(w)
	if err != nil {
		return "", err
	}
	var buf strings.Builder
	zw := zlib.NewWriter(&dumpWriter{b: &buf})
	if _, err := zw.Write(data); err != nil {
		return "", err
	}
	if err := zw.Close(); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString([]byte(buf.String())), nil
}

// UnmarshalWatches parses the watches dump
func UnmarshalWatches(dump string) (Watches, error) {
	data, err := decodeDump(dump)
	if err != nil {
		return nil, err
	}
	var w Watches
	if err := json.Unmarshal(data, &w); err != nil {
		return nil, err
	}
	return w, nil
}

// NewWatch creates a watch entry for the given path
func NewWatch(path string) Watch {
	w := Watch{Path: path}
	st, err := os.Stat(path)
	if err != nil {
		return w
	}
	w.Exists = true
	w.ModTime = st.ModTime().Unix()
	return w
}

// AddPaths adds the given paths to the watch list
func (w Watches) AddPaths(paths []string) Watches {
	for _, p := range paths {
		w = w.AddPath(p)
	}
	return w
}

// AddPath adds a single path to the watch list
func (w Watches) AddPath(path string) Watches {
	if path == "" {
		return w
	}
	path, _ = filepath.Abs(path)
	w = w.RemovePath(path)
	return append(w, NewWatch(path))
}

// RemovePath removes a path from the watch list
func (w Watches) RemovePath(path string) Watches {
	out := Watches{}
	for _, x := range w {
		if x.Path != path {
			out = append(out, x)
		}
	}
	return out
}

// HasPath returns whether the path is watched
func (w Watches) HasPath(path string) bool {
	for _, x := range w {
		if x.Path == path {
			return true
		}
	}
	return false
}

// IsStale returns whether any of the watched files changed
func (w Watches) IsStale() bool {
	for _, x := range w {
		if x.IsStale() {
			return true
		}
	}
	return false
}

// IsStale returns whether this single watch is stale
func (w Watch) IsStale() bool {
	st, err := os.Stat(w.Path)
	if err != nil {
		return w.Exists
	}
	if !w.Exists {
		return true
	}
	return st.ModTime().Unix() != w.ModTime
}

// AddDir recursively adds all files in dir to the watch list
func (w Watches) AddDir(dir string) Watches {
	dir, _ = filepath.Abs(dir)
	w = w.AddPath(dir)
	filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		w = w.AddPath(path)
		return nil
	})
	return w
}

// ParseWatchesFromEnv reads the watch list from the DIRENV_WATCHES env var
func ParseWatchesFromEnv() (Watches, error) {
	v := os.Getenv("DIRENV_WATCHES")
	if v == "" {
		return nil, fmt.Errorf("no watches")
	}
	return UnmarshalWatches(v)
}
