package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// RC states
const (
	// Allowed means the rc is allowed to execute
	Allowed = iota
	// Blocked means that this specific file version is blocked
	Blocked
	// Denied means the rc file has been denied execution explicitly
	Denied
)

// RC is a loaded .envrc or .env file
type RC struct {
	Path      string
	Dir       string
	Contents  []byte
	AllowPath string
	DenyPath  string
	Allowed   int
}

// FindRC walks up from the current directory looking for a .envrc (or .env)
// file.
func FindRC() *RC {
	pwd, err := os.Getwd()
	if err != nil {
		return nil
	}
	for {
		path := filepath.Join(pwd, ".envrc")
		if st, err := os.Stat(path); err == nil && !st.IsDir() {
			return NewRC(path)
		}
		if config.LoadDotenv {
			path = filepath.Join(pwd, ".env")
			if st, err := os.Stat(path); err == nil && !st.IsDir() {
				return NewRC(path)
			}
		}
		parent := filepath.Dir(pwd)
		if parent == pwd {
			return nil
		}
		pwd = parent
	}
}

// NewRC creates an RC record for the given path
func NewRC(path string) *RC {
	rc := &RC{Path: path}
	abs, err := filepath.Abs(path)
	if err == nil {
		rc.Path = abs
	}
	rc.Dir = filepath.Dir(rc.Path)
	data, err := os.ReadFile(rc.Path)
	if err != nil {
		data = []byte{}
	}
	rc.Contents = data
	rc.AllowPath = allowPath(rc.Path, data)
	rc.DenyPath = denyPath(rc.Path)
	switch {
	case fileExists(rc.DenyPath):
		rc.Allowed = Denied
	case fileExists(rc.AllowPath):
		rc.Allowed = Allowed
	default:
		rc.Allowed = Blocked
	}
	// whitelisted files are implicitly allowed
	if rc.Allowed == Blocked && rc.Whitelisted() {
		rc.Allowed = Allowed
	}
	return rc
}

// Whitelisted returns whether the rc file matches a whitelist entry
func (rc *RC) Whitelisted() bool {
	for _, prefix := range config.WhitelistPrefix {
		prefix = ExpandHome(prefix)
		if strings.HasPrefix(rc.Path, prefix) {
			return true
		}
	}
	for exact := range config.WhitelistExact {
		if rc.Path == exact {
			return true
		}
		if rc.Path == exact+"/.envrc" {
			return true
		}
	}
	return false
}

func fileExists(path string) bool {
	st, err := os.Stat(path)
	return err == nil && !st.IsDir()
}

// allowPath computes the path of the allow record for the given rc file
func allowPath(path string, contents []byte) string {
	h := sha256.New()
	h.Write([]byte(path + "\n"))
	h.Write(contents)
	return filepath.Join(config.DataDir, "allow", hex.EncodeToString(h.Sum(nil)))
}

// denyPath computes the path of the deny record for the given rc file
func denyPath(path string) string {
	h := sha256.New()
	h.Write([]byte(path + "\n"))
	return filepath.Join(config.DataDir, "deny", hex.EncodeToString(h.Sum(nil)))
}

// Allow records the rc file as allowed
func (rc *RC) Allow() error {
	if err := os.MkdirAll(filepath.Dir(rc.AllowPath), 0755); err != nil {
		return err
	}
	if err := os.WriteFile(rc.AllowPath, []byte(rc.Path+"\n"), 0644); err != nil {
		return err
	}
	if fileExists(rc.DenyPath) {
		if err := os.Remove(rc.DenyPath); err != nil {
			return err
		}
	}
	return nil
}

// Deny records the rc file as denied
func (rc *RC) Deny() error {
	if err := os.MkdirAll(filepath.Dir(rc.DenyPath), 0755); err != nil {
		return err
	}
	if err := os.WriteFile(rc.DenyPath, []byte(rc.Path+"\n"), 0644); err != nil {
		return err
	}
	if fileExists(rc.AllowPath) {
		if err := os.Remove(rc.AllowPath); err != nil {
			return err
		}
	}
	return nil
}

// WatchList returns the watch list for the rc file
func (rc *RC) WatchList() Watches {
	w := Watches{}
	if rc == nil {
		return w
	}
	w = w.AddPath(rc.Path)
	w = w.AddPath(rc.AllowPath)
	w = w.AddPath(rc.DenyPath)
	return w
}

// RequiredPath returns the path of the required-files record for an envrc
func RequiredPath(envrc string) string {
	return filepath.Join(config.DataDir, "allow", "required", hashKey(envrc))
}

// hashKey hashes a key for the DB
func hashKey(key string) string {
	h := sha256.New()
	h.Write([]byte(key + "\n"))
	return hex.EncodeToString(h.Sum(nil))
}

// String renders the RC for debugging
func (rc *RC) String() string {
	if rc == nil {
		return ""
	}
	return rc.Path
}

// checkRequired verifies that the given files have been allowed
func checkRequired(shellName, envrc string, paths []string) (string, error) {
	sh := Detect(shellName)
	w := Watches{}
	for _, p := range paths {
		w = w.AddPath(p)
	}
	var bad []string
	for _, p := range paths {
		rc := NewRC(p)
		if rc.Allowed != Allowed {
			bad = append(bad, p)
		}
	}
	if len(bad) == 0 {
		return "", nil
	}
	watchDump, err := w.MarshalDump()
	if err != nil {
		return "", err
	}
	var out strings.Builder
	out.WriteString(sh.SetEnv("DIRENV_REQUIRED", strings.Join(paths, ":")))
	msg := ""
	if len(bad) == 1 {
		msg = fmt.Sprintf("%s requires approval. Run 'direnv allow' to approve.", bad[0])
	} else {
		msg = fmt.Sprintf("%s and %s require approval. Run 'direnv allow' to approve.",
			strings.Join(bad[:len(bad)-1], ", "), bad[len(bad)-1])
	}
	out.WriteString(sh.LogStatus(msg))
	out.WriteString("exit 0;\n")
	return out.String(), nil
}
