package main

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

// Shell is the interface implemented by the supported target shells
type Shell interface {
	// Name returns the canonical name of the shell
	Name() string
	// SetEnv renders a shell command that sets the given variable
	SetEnv(k, v string) string
	// UnsetEnv renders a shell command that unsets the given variable
	UnsetEnv(k string) string
	// Dump renders the whole environment
	Dump(env Env) string
}

// shells holds all the supported shells
var shells = map[string]Shell{}

// Detect returns the shell with the given name
func Detect(name string) Shell {
	sh, ok := shells[name]
	if !ok {
		return nil
	}
	return sh
}

// ShellNames returns all the supported shell names
func ShellNames() []string {
	var out []string
	for k := range shells {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// bashEscape escapes a value using the ANSI-C quoting rules of bash
func bashEscape(v string) string {
	var b strings.Builder
	for _, c := range []byte(v) {
		switch c {
		case '\t':
			b.WriteString("\\t")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\'':
			b.WriteString("\\'")
		case '\\':
			b.WriteString("\\\\")
		default:
			if c < 0x20 || c >= 0x7f {
				b.WriteString(fmt.Sprintf("\\x%02x", c))
			} else {
				b.WriteByte(c)
			}
		}
	}
	return b.String()
}

// reSafeEnvValue matches values that can be emitted without quoting
func isSafeEnvValue(v string) bool {
	if v == "" {
		return false
	}
	for i := 0; i < len(v); i++ {
		c := v[i]
		switch {
		case c >= '0' && c <= '9':
		case c >= 'A' && c <= 'Z':
		case c == '_' || c == '-' || c == '.' || c == '/' || c == '@' || c == ',':
		default:
			return false
		}
	}
	return true
}

// bashSetEnv renders an export statement for bash-like shells
func bashSetEnv(k, v string) string {
	if isSafeEnvValue(v) {
		return fmt.Sprintf("export %s=%s;", k, v)
	}
	if v == "" {
		return fmt.Sprintf("export %s='';", k)
	}
	return fmt.Sprintf("export %s=$'%s';", k, bashEscape(v))
}

// fishEscape escapes a value for fish
func fishEscape(v string) string {
	var b strings.Builder
	b.WriteString("'")
	for _, c := range []byte(v) {
		switch c {
		case '\'':
			b.WriteString("\\'")
		case '\\':
			b.WriteString("\\\\")
		case '\t':
			b.WriteString("'\\t'")
		case '\n':
			b.WriteString("'\\n'")
		case '\r':
			b.WriteString("'\\r'")
		default:
			if c < 0x20 || c >= 0x7f {
				b.WriteString(fmt.Sprintf("'\\x%02x'", c))
			} else {
				b.WriteByte(c)
			}
		}
	}
	b.WriteString("'")
	return b.String()
}

// fishSetEnv renders a fish set statement
func fishSetEnv(k, v string) string {
	if k == "PATH" {
		var parts []string
		if v != "" {
			parts = strings.Split(v, ":")
		}
		args := make([]string, 0, len(parts))
		for _, p := range parts {
			args = append(args, fishEscape(p))
		}
		return fmt.Sprintf("set -x -g PATH %s;", strings.Join(args, " "))
	}
	return fmt.Sprintf("set -x -g %s %s;", fishEscape(k), fishEscape(v))
}

// fishUnsetEnv renders a fish unset statement
func fishUnsetEnv(k string) string {
	return fmt.Sprintf("set -e -g %s;", fishEscape(k))
}

// tcshEscape escapes a value for tcsh
