			b.WriteString("'\\n'")
		case '\r':
			b.WriteString("'\\r'")
		default:
			if c < 0x20 || c >= 0x7f {
				b.WriteString(fmt.Sprintf("'\\x%02x'", c))
			} else {
				b.WriteByte(c)
			}
		}
	}
	b.WriteString("'")
	return b.String()
}

// fishSetEnv renders a fish set statement
func fishSetEnv(k, v string) string {
	if k == "PATH" {
		var parts []string
		if v != "" {
			parts = strings.Split(v, ":")
		}
		args := make([]string, 0, len(parts))
		for _, p := range parts {
			args = append(args, fishEscape(p))
		}
		return fmt.Sprintf("set -x -g PATH %s;", strings.Join(args, " "))
	}
	return fmt.Sprintf("set -x -g %s %s;", fishEscape(k), fishEscape(v))
}

// fishUnsetEnv renders a fish unset statement
func fishUnsetEnv(k string) string {
	return fmt.Sprintf("set -e -g %s;", fishEscape(k))
}

// tcshEscape escapes a value for tcsh
func tcshEscape(v string) string {
	var b strings.Builder
	for _, c := range []byte(v) {
		switch c {
		case '\t':
			b.WriteString("\\t")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\'':
			b.WriteString("\\'")
		case '\\':
			b.WriteString("\\\\")
		case ' ':
			b.WriteString("\\ ")
		case '!':
			b.WriteString(`"!"`)
		case '"':
			b.WriteString(`""`)
		case '#':
			b.WriteString(`"#"`)
		case '$':
			b.WriteString(`"$"`)
		case '%':
			b.WriteString(`"%"`)
		case '&':
			b.WriteString(`"&"`)
		case '(':
			b.WriteString(`"("`)
		case ')':
			b.WriteString(`")"`)
		case '*':
			b.WriteString(`"*"`)
		case '+':
			b.WriteString(`"+"`)
		case ':':
			b.WriteString(`":"`)
		case ';':
			b.WriteString(`";"`)
		case '<':
			b.WriteString(`"<"`)
		case '=':
			b.WriteString(`"="`)
		case '>':
			b.WriteString(`">"`)
		case '?':
			b.WriteString(`"?"`)
		case '[':
			b.WriteString(`"["`)
		case '{':
			b.WriteString(`"{"`)
		case '|':
			b.WriteString(`"|"`)
		case '}':
			b.WriteString(`"}"`)
		case '~':
			b.WriteString(`"~"`)
		default:
			if c < 0x20 || c >= 0x7f {
				b.WriteString(fmt.Sprintf("\\x%02x", c))
			} else {
				b.WriteByte(c)
			}
		}
	}
	return b.String()
}

