// jsonEscapeNoHTML escapes a string without HTML escaping (like elvish)
func jsonMarshalNoHTML(env Env) string {
	keys := env.Keys()
	var b strings.Builder
	b.WriteString("{")
	for i, k := range keys {
		if i > 0 {
			b.WriteString(",")
		}
		kb, _ := json.Marshal(k)
		vb, _ := json.Marshal(env[k])
		b.WriteString(string(kb))
		b.WriteString(":")
		b.WriteString(string(vb))
	}
	b.WriteString("}")
	return b.String()
