package main

import (
	"strconv"
	"strings"
)

// semVer is a parsed semantic version
type semVer struct {
	nums []int
}

func parseSemVer(s string) (semVer, bool) {
	s = strings.TrimPrefix(s, "v")
	parts := strings.Split(s, ".")
	var nums []int
	for _, p := range parts {
		n, err := strconv.Atoi(p)
		if err != nil {
			return semVer{}, false
		}
		nums = append(nums, n)
	}
	if len(nums) == 0 {
		return semVer{}, false
	}
	return semVer{nums: nums}, true
}

// Less returns whether v is older than o
func (v semVer) Less(o semVer) bool {
	for i := 0; i < len(v.nums) || i < len(o.nums); i++ {
		var a, b int
		if i < len(v.nums) {
			a = v.nums[i]
		}
		if i < len(o.nums) {
			b = o.nums[i]
		}
		if a != b {
			return a < b
		}
	}
	return false
}
GOEOF
