func shellList() string {
	return "[" + strings.Join(ShellNames(), ", ") + "]"
}

// lookupCommand finds a command by name or alias
func lookupCommand(name string) *cmd {
	for _, c := range commands {
		if c.UsageLine == name {
			return c
		}
		n := strings.SplitN(c.UsageLine, " ", 2)[0]
		if n == name {
			return c
		}
		for _, a := range c.Alias {
			if a == name {
				return c
			}
		}
	}
	return nil
}

func cmdHelp(args []string) error {
	showPrivate := len(args) > 0
	fmt.Printf("direnv v%s\n", Version)
	fmt.Println("Usage: direnv COMMAND [...ARGS]")
	fmt.Println()
	fmt.Println("Available commands")
	fmt.Println("------------------")
	for _, c := range commands {
		if c.Private && !showPrivate {
			continue
		}
		fmt.Printf("%s:\n", c.UsageLine)
		if len(c.Alias) > 0 {
			fmt.Printf("  aliases: %s\n", strings.Join(c.Alias, ", "))
		}
		for _, l := range strings.Split(c.Short, "\n") {
			fmt.Printf("  %s\n", l)
		}
	}
	if showPrivate {
		fmt.Println("* = private commands")
	}
	return nil
}

func cmdVersion(args []string) error {
	if len(args) == 0 {
		fmt.Println(Version)
		return nil
	}
	want := args[0]
	if !strings.HasPrefix(want, "v") {
		want = "v" + want
	}
	cur := "v" + Version
	a, ok := parseSemVer(cur)
	if !ok {
		return fmt.Errorf("%s is not a valid semver version", cur)
	}
	b, ok := parseSemVer(want)
	if !ok {
		return fmt.Errorf("%s is not a valid semver version", want)
	}
	if a.Less(b) {
		return fmt.Errorf("current version %s is older than the desired version %s", cur, want)
	}
	return nil
}
