package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// userRelPath converts an absolute path into a user relative path when possible
func userRelPath(p string) string {
	home := os.Getenv("HOME")
	if home == "" {
		return p
	}
	if p == home {
		return "~"
	}
	if strings.HasPrefix(p, home+"/") {
		return "~" + p[len(home):]
	}
	return p
}

// cmdExport loads the current .envrc/.env and prints the diff in terms of
// exports for the given target shell.
func cmdExport(args []string) error {
	if len(args) < 1 {
		return fmt.Errorf("unknown target shell '%s'", "")
	}
	sh := Detect(args[0])
	if sh == nil {
		return fmt.Errorf("unknown target shell '%s'", args[0])
	}

	rc := FindRC()
	prevWatches, watchesErr := ParseWatchesFromEnv()
	var prevDiff *Diff
	if v := os.Getenv("DIRENV_DIFF"); v != "" {
		if d, err := UnmarshalDiff(v); err == nil {
			prevDiff = &d
		} else {
			return fmt.Errorf("Revert() failed: %s", err)
		}
	}

	origEnv := currentProcessEnv()

	// The environment the rc evaluation starts from
	baseEnv := Env{}
	for k, v := range origEnv {
		baseEnv[k] = v
	}

	needsReload := false
	if rc != nil {
		if os.Getenv("DIRENV_FILE") != rc.Path {
			needsReload = true
		}
		if watchesErr == nil && prevWatches.IsStale() {
			needsReload = true
		}
	}

	if needsReload && prevDiff != nil {
		for k := range prevDiff.n {
			delete(baseEnv, k)
		}
		for k, v := range prevDiff.p {
			baseEnv[k] = v
		}
	}

	// Remove the dump file path so it doesn't leak into the child
	dumpFilePath := os.Getenv("DIRENV_DUMP_FILE_PATH")

	// private keys that direnv manages
	baseEnv["DIRENV_DIR"] = ""
	baseEnv["DIRENV_FILE"] = ""
	if rc != nil {
		baseEnv["DIRENV_DIR"] = "-" + rc.Dir
		baseEnv["DIRENV_FILE"] = rc.Path
	}
	baseEnv["DIRENV_WATCHES"] = os.Getenv("DIRENV_WATCHES")

	newEnv := Env{}
	for k, v := range baseEnv {
		newEnv[k] = v
	}
	var loadErr error
	if rc != nil && rc.Allowed == Allowed {
		newEnv, loadErr = runRC(rc, baseEnv)
		if loadErr != nil {
			// the evaluation failed: keep the base environment
			newEnv = Env{}
			for k, v := range baseEnv {
				newEnv[k] = v
			}
		}
	} else if rc != nil && rc.Allowed == Blocked {
		loadErr = fmt.Errorf("%s is blocked. Run `direnv allow` to approve its content", rc.Path)
	}

	// Build the new watch list
	var newWatches Watches
	if wv, ok := newEnv["DIRENV_WATCHES"]; ok && wv != "" {
		if w, err := UnmarshalWatches(wv); err == nil {
			newWatches = w
		}
	}
	if rc != nil {
		newWatches = newWatches.AddPath(rc.Path)
		newWatches = newWatches.AddPath(rc.AllowPath)
		newWatches = newWatches.AddPath(rc.DenyPath)
	}
	watchDump, err := newWatches.MarshalDump()
	if err != nil {
		return err
	}
	newEnv["DIRENV_WATCHES"] = watchDump

	// No rc found: maybe we need to unload
	if rc == nil {
		prevRCPath := os.Getenv("DIRENV_FILE")
		if prevDiff != nil {
			prevRCPath = prevDiff.n["DIRENV_FILE"]
		}
		if prevRCPath != "" && watchesErr == nil {
			LogStatus("unloading")
			var out strings.Builder
			for _, k := range []string{"DIRENV_DIR", "DIRENV_FILE", "DIRENV_WATCHES", "DIRENV_DIFF"} {
				if _, ok := origEnv[k]; ok {
					out.WriteString(sh.UnsetEnv(k))
				}
			}
			if prevDiff != nil {
				rev := prevDiff.Revert()
				for _, k := range rev.n.Keys() {
					out.WriteString(sh.SetEnv(k, rev.n[k]))
				}
				for _, k := range rev.p.Keys() {
					if _, ok := origEnv[k]; ok {
						out.WriteString(sh.UnsetEnv(k))
					}
				}
			}
			fmt.Print(out.String())
			return nil
		}
		return nil
	}

	// Compute the diff
	diff := DiffOf(baseEnv, newEnv)
	changes := diff.Log()
	if needsReload {
		LogStatus("loading %s", userRelPath(rc.Path))
	}
	if strings.TrimSpace(strings.TrimPrefix(changes, "export ")) != "" {
		LogStatus("%s", changes)
	}

	newDiff := Diff{p: Env{}, n: Env{}}
	for k, v := range diff.n {
		newDiff.n[k] = v
	}
	for k, v := range diff.p {
		newDiff.p[k] = v
	}
	diffDump, err := newDiff.MarshalDump()
	if err != nil {
		return err
	}

	// The final environment, used to decide which exports to emit
	finalEnv := Env{}
	for k, v := range newEnv {
		finalEnv[k] = v
	}
	finalEnv["DIRENV_DIFF"] = diffDump

	var out strings.Builder
	for _, k := range diff.p.Keys() {
		if _, ok := finalEnv[k]; ok {
			continue
		}
		if _, ok := origEnv[k]; ok {
			out.WriteString(sh.UnsetEnv(k))
		}
	}
	for _, k := range diff.n.Keys() {
		v := finalEnv[k]
		if ov, ok := origEnv[k]; ok && ov == v {
			continue
		}
		out.WriteString(sh.SetEnv(k, v))
	}
	for _, k := range []string{"DIRENV_DIFF", "DIRENV_WATCHES"} {
		v := finalEnv[k]
		if ov, ok := origEnv[k]; ok && ov == v {
			continue
		}
		out.WriteString(sh.SetEnv(k, v))
	}
	_ = dumpFilePath
	fmt.Print(out.String())
	return loadErr
}
GOEOF
echo ok"}

