package main

import (
	"bytes"
	"context"
	_ "embed"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

//go:embed stdlib.sh
var stdlibTemplate string

// Stdlib returns the stdlib script with the direnv path substituted
func Stdlib() string {
	return strings.ReplaceAll(stdlibTemplate, "%DIRENV%", config.SelfPath)
}

// rcScript builds the bash script used to evaluate an .envrc file
func rcScript(rc *RC) string {
	var b strings.Builder
	b.WriteString(Stdlib())
	b.WriteString("\n")
	fmt.Fprintf(&b, "cd %q\n", rc.Dir)
	fmt.Fprintf(&b, "__main__ source %q %q\n", "./"+filepath.Base(rc.Path), rc.Path)
	return b.String()
}

// runRC evaluates the rc file in a bash sub-shell and returns the resulting
// environment.
func runRC(rc *RC, env Env) (Env, error) {
	childEnv := os.Environ()
	childEnv = filterEnvPrefixes(childEnv, []string{"DIRENV_DIR=", "DIRENV_FILE=", "DIRENV_DIFF="})
	for k, v := range env {
		if k == "DIRENV_DIR" || k == "DIRENV_FILE" || k == "DIRENV_DIFF" {
			continue
		}
		childEnv = setEnvValue(childEnv, k, v)
	}

	ctx := context.Background()
	var cancel context.CancelFunc
	if config.WarnTimeout > 0 {
		ctx, cancel = context.WithTimeout(ctx, config.WarnTimeout)
		defer cancel()
		go func() {
			<-ctx.Done()
			if ctx.Err() != nil {
				return
			}
		}()
	}

	cmd := exec.Command(config.BashPath, "-c", rcScript(rc), config.BashPath, rc.Path)
	cmd.Env = childEnv
	cmd.Dir = rc.Dir
	if config.DisableStdin {
		devNull, err := os.OpenFile(os.DevNull, os.O_RDONLY, 0)
		if err == nil {
			cmd.Stdin = devNull
			defer devNull.Close()
		}
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return nil, err
	}
	cmd.Stderr = os.Stderr

	if err := cmd.Start(); err != nil {
		return nil, err
	}

	warnDone := make(chan struct{})
	if config.WarnTimeout > 0 {
		go func() {
			select {
			case <-time.After(config.WarnTimeout):
				LogStatus("command is taking too long. That's weird...")
			case <-warnDone:
			}
		}()
	}

	data, readErr := io.ReadAll(stdout)
	waitErr := cmd.Wait()
	close(warnDone)

	if waitErr != nil {
		if ctx.Err() != nil {
			return nil, fmt.Errorf("timed out")
		}
	}
	_ = waitErr

	if readErr != nil {
		return nil, readErr
	}
	env, err := parseDumpOutput(data)
	if err != nil {
		return nil, err
	}
	return env, nil
}

// parseDumpOutput parses the JSON dump produced by the rc evaluation
func parseDumpOutput(data []byte) (Env, error) {
	env := Env{}
	if err := jsonUnmarshalStrict(bytes.TrimSpace(data), &env); err != nil {
		return nil, err
	}
	return env, nil
}

// filterEnvPrefixes removes entries with the given prefixes
func filterEnvPrefixes(env []string, prefixes []string) []string {
	out := make([]string, 0, len(env))
	for _, kv := range env {
		skip := false
		for _, p := range prefixes {
			if strings.HasPrefix(kv, p) {
				skip = true
				break
			}
		}
		if !skip {
			out = append(out, kv)
		}
	}
	return out
}

// setEnvValue sets or replaces a value in an environment slice
func setEnvValue(env []string, k, v string) []string {
	prefix := k + "="
	out := make([]string, 0, len(env)+1)
	found := false
	for _, kv := range env {
		if strings.HasPrefix(kv, prefix) {
			out = append(out, prefix+v)
			found = true
			continue
		}
		out = append(out, kv)
	}
	if !found {
		out = append(out, prefix+v)
	}
	return out
}
