package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// cmdAllow implements `direnv allow`
func cmdAllow(args []string) error {
	rc, err := rcFromArgs(args)
	if err != nil {
		return err
	}
	return rc.Allow()
}

// cmdBlock implements `direnv block`
func cmdBlock(args []string) error {
	rc, err := rcFromArgs(args)
	if err != nil {
		return err
	}
	return rc.Deny()
}

// rcFromArgs resolves the rc file from the command arguments
func rcFromArgs(args []string) (*RC, error) {
	if len(args) == 0 {
		rc := FindRC()
		if rc == nil {
			return nil, fmt.Errorf(".envrc file not found")
		}
		return rc, nil
	}
	path := args[0]
	path = ExpandHome(path)
	if !filepath.IsAbs(path) {
		path, _ = filepath.Abs(path)
	}
	st, err := os.Stat(path)
	if err != nil {
		return nil, err
	}
	if st.IsDir() {
		path = filepath.Join(path, ".envrc")
		if _, err := os.Stat(path); err != nil {
			return nil, fmt.Errorf(".envrc file not found")
		}
	}
	return NewRC(path), nil
}

// cmdReload implements `direnv reload`
func cmdReload(args []string) error {
	// Remove the watches so the next export re-evaluates the rc file
	os.Unsetenv("DIRENV_WATCHES")
	return nil
}

// cmdEdit implements `direnv edit`
func cmdEdit(args []string) error {
	rc, err := rcFromArgs(args)
	if err != nil {
		return err
	}
	editor := os.Getenv("EDITOR")
	if editor == "" {
		LogErrorPlain("$EDITOR not found.")
		return fmt.Errorf("could not find a default editor in the PATH")
	}
	editor, err = execLookPath(editor)
	if err != nil {
		LogErrorPlain("$EDITOR not found.")
		return fmt.Errorf("could not find a default editor in the PATH")
	}
	editor = ExpandHome(editor)
	editor = filepath.Clean(editor)
	argv := []string{editor, rc.Path}
	if os.Getenv("DIRENV_EDITOR_FLAGS") != "" {
		argv = append(strings.Fields(os.Getenv("DIRENV_EDITOR_FLAGS")), argv...)
	}
	proc := osProcess(argv)
	proc.Stdin = os.Stdin
	proc.Stdout = os.Stdout
	proc.Stderr = os.Stderr
	if err := proc.Run(); err != nil {
		return err
	}
	// reload the contents and allow it
	rc = NewRC(rc.Path)
	return rc.Allow()
}

// cmdExec implements `direnv exec`
func cmdExec(args []string) error {
	if len(args) < 1 {
		return fmt.Errorf("missing DIR and COMMAND arguments")
	}
	if len(args) < 2 {
		return fmt.Errorf("missing COMMAND argument")
	}
	dir := args[0]
	if _, err := os.Stat(dir); err != nil {
		return err
	}
	abs, err := filepath.Abs(dir)
	if err != nil {
		return err
	}
	rc := findRCIn(abs)
	if rc == nil {
		return fmt.Errorf("no .envrc or .env found in %s", abs)
	}
	if rc.Allowed != Allowed {
		return fmt.Errorf("%s is blocked. Run `direnv allow` to approve its content", rc.Path)
	}
	env := currentProcessEnv()
	newEnv, err := runRC(rc, env)
	if err != nil {
		return err
	}
	// apply the new environment
	for _, kv := range os.Environ() {
		i := strings.Index(kv, "=")
		if i < 0 {
			continue
		}
		k := kv[:i]
		if _, ok := newEnv[k]; !ok {
			if !ignoredEnvKeys[k] && !isPrivateEnvKey(k) {
				os.Unsetenv(k)
			}
		}
	}
	for k, v := range newEnv {
		os.Setenv(k, v)
	}
	bin, err := execLookPath(args[1])
	if err != nil {
		return err
	}
	proc := osProcess(append([]string{bin}, args[2:]...))
	proc.Stdin = os.Stdin
	proc.Stdout = os.Stdout
	proc.Stderr = os.Stderr
	proc.Dir = abs
	return proc.Run()
}

// findRCIn finds an rc file in the given directory (without walking up)
func findRCIn(dir string) *RC {
	path := filepath.Join(dir, ".envrc")
	if st, err := os.Stat(path); err == nil && !st.IsDir() {
		return NewRC(path)
	}
	if config.LoadDotenv {
		path = filepath.Join(dir, ".env")
		if st, err := os.Stat(path); err == nil && !st.IsDir() {
			return NewRC(path)
		}
	}
	return nil
}

// cmdStdlib implements `direnv stdlib`
func cmdStdlib(args []string) error {
	fmt.Print(Stdlib())
	return nil
}

// cmdLog implements `direnv log`
func cmdLog(args []string) error {
	isError := false
	var msg []string
	for _, a := range args {
		switch a {
		case "--status", "-status":
			isError = false
		case "--error", "-error":
			isError = true
		default:
			msg = append(msg, a)
		}
	}
	if len(msg) == 0 {
		return fmt.Errorf("invalid arguments")
	}
	if isError {
		LogErrorPlain(strings.Join(msg, " "))
	} else {
		LogStatus(strings.Join(msg, " "))
	}
	return nil
}

// statusState is the JSON structure of `direnv status --json`
type statusState struct {
	FoundRC  *rcInfo `json:"foundRC"`
	LoadedRC *rcInfo `json:"loadedRC"`
}

type rcInfo struct {
	Allowed int    `json:"allowed"`
	Path    string `json:"path"`
}

type statusConfig struct {
	ConfigDir string `json:"ConfigDir"`
	SelfPath  string `json:"SelfPath"`
}

type statusJSON struct {
	Config statusConfig `json:"config"`
	State  statusState  `json:"state"`
}

// cmdStatus implements `direnv status`
func cmdStatus(args []string) error {
	if len(args) > 0 && args[0] == "--json" {
		out := statusJSON{
			Config: statusConfig{ConfigDir: config.ConfigDir, SelfPath: config.SelfPath},
		}
		if rc := FindRC(); rc != nil {
			out.State.FoundRC = &rcInfo{Allowed: rc.Allowed, Path: rc.Path}
		}
		if rc := loadedRC(); rc != nil {
			out.State.LoadedRC = &rcInfo{Allowed: rc.Allowed, Path: rc.Path}
		}
		data, err := json.MarshalIndent(out, "", "  ")
		if err != nil {
			return err
		}
		fmt.Println(string(data))
		return nil
	}
	fmt.Printf("direnv exec path %s\n", config.SelfPath)
	fmt.Printf("DIRENV_CONFIG %s\n", config.ConfigDir)
	fmt.Printf("bash_path %s\n", config.BashPath)
	fmt.Printf("disable_stdin %t\n", config.DisableStdin)
	fmt.Printf("warn_timeout %s\n", config.WarnTimeout)
	fmt.Printf("whitelist.prefix %v\n", config.WhitelistPrefix)
	fmt.Printf("whitelist.exact %v\n", toMapStringBool(config.WhitelistExact))
	if rc := loadedRC(); rc != nil {
		fmt.Printf("Loaded RC path %s\n", rc.Path)
		printWatches("Loaded", rc)
		fmt.Printf("Loaded RC allowed %d\n", rc.Allowed)
		fmt.Printf("Loaded RC allowPath %s\n", rc.AllowPath)
	} else {
		fmt.Printf("No .envrc or .env loaded\n")
	}
	if rc := FindRC(); rc != nil {
		fmt.Printf("Found RC path %s\n", rc.Path)
		printWatches("Found", rc)
		fmt.Printf("Found RC allowed %d\n", rc.Allowed)
		fmt.Printf("Found RC allowPath %s\n", rc.AllowPath)
	} else {
		fmt.Printf("No .envrc or .env found\n")
	}
	return nil
}

// loadedRC returns the RC that was loaded previously, based on the
// environment.
func loadedRC() *RC {
	if os.Getenv("DIRENV_FILE") == "" {
		return nil
	}
	if _, err := ParseWatchesFromEnv(); err != nil {
		return nil
	}
	return NewRC(os.Getenv("DIRENV_FILE"))
}

// printWatches prints the watch list of an rc file
func printWatches(prefix string, rc *RC) {
	w := rc.WatchList()
	pwd, _ := os.Getwd()
	for _, x := range w {
		rel, err := filepath.Rel(pwd, x.Path)
		if err != nil {
			rel = x.Path
		}
		fmt.Printf("%s watch: %q - %s\n", prefix, rel, time.Unix(x.ModTime, 0).UTC().Format(time.RFC3339))
	}
}

func toMapStringBool(m map[string]bool) map[string]bool {
	out := map[string]bool{}
	for k, v := range m {
		out[k] = v
	}
	return out
}
GOEOF
