// cmdFetchurl implements `direnv fetchurl`
func cmdFetchurl(args []string) error {
	if len(args) < 1 {
		return fmt.Errorf("missing URL argument")
	}
	url := args[0]
	var wantHash *SRI
	if len(args) > 1 {
		sri, err := ParseSRI(args[1])
		if err != nil {
			return err
		}
		wantHash = &sri
	}
	body, err := httpGet(url)
	if err != nil {
		return err
	}
	sum := sha256.Sum256(body)
	got := SRI{Algo: "sha256", Hash: base64.RawURLEncoding.EncodeToString(sum[:])}
	if wantHash == nil {
		fmt.Println(got.String())
		if isatty(os.Stdout) {
			fmt.Println()
			fmt.Println("Invoke fetchurl again with the hash as an argument to get the disk location:")
			fmt.Println()
			fmt.Printf("  %s fetchurl %q %q\n", config.SelfPath, url, got.String())
			fmt.Printf("  #=> %s\n", casPath(got.String()))
		}
		return nil
	}
	if wantHash.Algo != "sha256" {
		return fmt.Errorf("sri: unsupported algo %s", wantHash.Algo)
	}
	if wantHash.String() != got.String() {
		return fmt.Errorf("integrity check failed for %s: got %s", url, got.String())
	}
	path, err := casWrite(got.String(), body)
	if err != nil {
		return err
	}
	fmt.Println(path)
	return nil
}

// SRI is a Subresource Integrity hash
type SRI struct {
	Algo string
	Hash string
}

// String renders the SRI hash
func (s SRI) String() string { return s.Algo + "-" + s.Hash }

// ParseSRI parses an SRI hash string
func ParseSRI(s string) (SRI, error) {
	i := strings.Index(s, "-")
	if i < 0 {
		return SRI{}, fmt.Errorf("sri: not a hash %s", s)
	}
	algo := s[:i]
	hashStr := s[i+1:]
	switch algo {
	case "sha256", "sha384", "sha512":
	default:
		return SRI{}, fmt.Errorf("sri: unsupported algo %s", algo)
	}
	data, err := base64.URLEncoding.DecodeString(hashStr)
	if err != nil {
		return SRI{}, err
	}
	return SRI{Algo: algo, Hash: hashStr}, nil
}

// casPath returns the on-disk location for a hash
func casPath(sri string) string {
	return filepath.Join(XDGCacheHome(), "direnv", "cas", strings.ReplaceAll(sri, "/", "_"))
}

// casWrite writes the content into the CAS
func casWrite(sri string, data []byte) (string, error) {
	path := casPath(sri)
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		return "", err
	}
	if _, err := os.Stat(path); err == nil {
		return path, nil
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0555); err != nil {
		return "", err
	}
	if err := os.Chmod(tmp, 0555); err != nil {
		return "", err
	}
	if err := os.Rename(tmp, path); err != nil {
		return "", err
	}
	return path, nil
}

// hasherFor returns the hash function for the given algorithm
func hasherFor(algo string) hash.Hash {
	switch algo {
	case "sha256":
		return sha256.New()
	case "sha384":
		return sha512.New384()
	case "sha512":
		return sha512.New()
	}
	return nil
}

func hashHex(algo string, data []byte) string {
	h := hasherFor(algo)
	h.Write(data)
	return hex.EncodeToString(h.Sum(nil))
}

// httpGet fetches a URL following redirects
func httpGet(url string) ([]byte, error) {
	client := &http.Client{}
	resp, err := client.Get(url)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("http GET failed for %s: %s", url, resp.Status)
	}
	return io.ReadAll(resp.Body)
}

func isatty(f *os.File) bool {
	st, err := f.Stat()
	if err != nil {
		return false
	}
	return st.Mode()&os.ModeCharDevice != 0
}

// cmdPrune implements `direnv prune`
func cmdPrune(args []string) error {
	return pruneDB()
}

// pruneDB removes the invalid entries from the allow DB
func pruneDB() error {
	dir := filepath.Join(config.DataDir, "allow")
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		path := filepath.Join(dir, e.Name())
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		rcPath := strings.TrimRight(string(data), "\n")
		if rcPath == "" {
			_ = os.Remove(path)
			continue
		}
		if !fileExists(rcPath) {
			_ = os.Remove(path)
			continue
		}
		content, err := os.ReadFile(rcPath)
		if err != nil {
			_ = os.Remove(path)
			continue
		}
		if allowPath(rcPath, content) != path {
			_ = os.Remove(path)
		}
	}
	reqDir := filepath.Join(config.DataDir, "allow", "required")
	if entries, err := os.ReadDir(reqDir); err == nil {
		for _, e := range entries {
			if e.IsDir() {
				continue
			}
			path := filepath.Join(reqDir, e.Name())
			data, err := os.ReadFile(path)
			if err != nil {
				continue
			}
			rcPath := strings.TrimRight(string(data), "\n")
			if rcPath == "" || !fileExists(rcPath) {
				_ = os.Remove(path)
			}
		}
	}
	return nil
}
