	if err := os.Chmod(tmp, 0555); err != nil {
		return "", err
	}
	if err := os.Rename(tmp, path); err != nil {
		return "", err
	}
	return path, nil
}

// hasherFor returns the hash function for the given algorithm
func hasherFor(algo string) hash.Hash {
	switch algo {
	case "sha256":
		return sha256.New()
	case "sha384":
		return sha512.New384()
	case "sha512":
		return sha512.New()
	}
	return nil
}

func hashHex(algo string, data []byte) string {
	h := hasherFor(algo)
	h.Write(data)
	return hex.EncodeToString(h.Sum(nil))
}

// httpGet fetches a URL following redirects
func httpGet(url string) ([]byte, error) {
	client := &http.Client{}
	resp, err := client.Get(url)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("http GET failed for %s: %s", url, resp.Status)
	}
	return io.ReadAll(resp.Body)
}

func isatty(f *os.File) bool {
	st, err := f.Stat()
	if err != nil {
		return false
	}
	return st.Mode()&os.ModeCharDevice != 0
}

// cmdPrune implements `direnv prune`
func cmdPrune(args []string) error {
	return pruneDB()
}

// pruneDB removes the invalid entries from the allow DB
func pruneDB() error {
	dir := filepath.Join(config.DataDir, "allow")
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		path := filepath.Join(dir, e.Name())
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		rcPath := strings.TrimRight(string(data), "\n")
		if rcPath == "" {
			_ = os.Remove(path)
			continue
		}
		if !fileExists(rcPath) {
			_ = os.Remove(path)
			continue
		}
		content, err := os.ReadFile(rcPath)
		if err != nil {
			_ = os.Remove(path)
			continue
		}
		if allowPath(rcPath, content) != path {
			_ = os.Remove(path)
		}
	}
	reqDir := filepath.Join(config.DataDir, "allow", "required")
	if entries, err := os.ReadDir(reqDir); err == nil {
		for _, e := range entries {
			if e.IsDir() {
				continue
			}
			path := filepath.Join(reqDir, e.Name())
			data, err := os.ReadFile(path)
			if err != nil {
				continue
			}
			rcPath := strings.TrimRight(string(data), "\n")
			if rcPath == "" || !fileExists(rcPath) {
				_ = os.Remove(path)
			}
		}
	}
	return nil
}
