	paths := args[2:]
	out, err := checkRequiredImpl(sh, envrc, paths)
	if err != nil {
		return err
	}
	fmt.Print(out)
	return nil
}

// checkRequiredImpl renders the bash code for require_allowed
func checkRequiredImpl(sh Shell, envrc string, paths []string) (string, error) {
	w := Watches{}
	for _, p := range paths {
		w = w.AddPath(p)
	}
	var bad []string
	for _, p := range paths {
		rc := NewRC(p)
		if rc.Allowed != Allowed {
			bad = append(bad, p)
		}
	}
	watchDump, err := w.MarshalDump()
	if err != nil {
		return "", err
	}
	var b strings.Builder
	b.WriteString(sh.SetEnv("DIRENV_WATCHES", watchDump))
	if len(bad) > 0 {
		msg := ""
		if len(bad) == 1 {
			msg = fmt.Sprintf("%s requires approval. Run 'direnv allow' to approve.", bad[0])
		} else {
			msg = fmt.Sprintf("%s and %s require approval. Run 'direnv allow' to approve.",
				strings.Join(bad[:len(bad)-1], ", "), bad[len(bad)-1])
		}
		b.WriteString(sh.LogStatus(msg))
	}
	return b.String(), nil
}

// osProcess creates an os/exec Cmd for the given argv
func osProcess(argv []string) *exec.Cmd {
	c := exec.Command(argv[0], argv[1:]...)
	return c
}
