	"os/exec"
	"strings"
)

//go:embed hooks/bash.txt
var hookBash string
//go:embed hooks/zsh.txt
var hookZsh string
//go:embed hooks/fish.txt
var hookFish string
//go:embed hooks/tcsh.txt
var hookTcsh string
//go:embed hooks/elvish.txt
var hookElvish string
//go:embed hooks/pwsh.txt
var hookPwsh string
//go:embed hooks/murex.txt
var hookMurex string

// cmdHook implements `direnv hook`
func cmdHook(args []string) error {
	if len(args) < 1 {
		return fmt.Errorf("unknown target shell '%s'", "")
	}
	var tpl string
	switch args[0] {
	case "bash":
		tpl = hookBash
	case "zsh":
		tpl = hookZsh
	case "fish":
		tpl = hookFish
	case "tcsh":
		tpl = hookTcsh
	case "elvish":
		tpl = hookElvish
	case "pwsh":
		tpl = hookPwsh
	case "murex":
		tpl = hookMurex
	case "gha":
		return fmt.Errorf("Hook not implemented for GitHub Actions shell")
	default:
		sh := Detect(args[0])
		if sh != nil && (sh.Name() == "json" || sh.Name() == "gzenv" || sh.Name() == "vim" || sh.Name() == "systemd") {
			return fmt.Errorf("this feature is not supported")
		}
		return fmt.Errorf("unknown target shell '%s'", args[0])
	}
	fmt.Print(strings.ReplaceAll(tpl, "{DIRENV}", config.SelfPath))
	return nil
}

// cmdDump implements `direnv dump`
func cmdDump(args []string) error {
	shellName := ""
	filePath := ""
	if len(args) > 0 {
		shellName = args[0]
	}
	if len(args) > 1 {
		filePath = args[1]
	}
	env := currentProcessEnv()
	// dump decrements SHLVL
	if v, ok := env["SHLVL"]; ok {
		var n int
		if _, err := fmt.Sscanf(v, "%d", &n); err == nil {
			env["SHLVL"] = fmt.Sprintf("%d", n-1)
		}
	}
	dumpFilePath := os.Getenv("DIRENV_DUMP_FILE_PATH")
	if filePath == "" {
		filePath = dumpFilePath
	}
	if shellName == "" {
		data, err := jsonMarshal(env)
		if err != nil {
			return err
		}
		d, err := encodeDump(data)
		if err != nil {
			return err
		}
		return writeOut(filePath, d)
	}
	sh := Detect(shellName)
	if sh == nil {
		return fmt.Errorf("unknown target shell '%s'", shellName)
	}
	out := sh.Dump(env)
	return writeOut(filePath, out)
}

// jsonMarshal returns the compact JSON of the environment
func jsonMarshal(env Env) ([]byte, error) {
	return jsonMarshalRaw(env)
}

func writeOut(filePath, data string) error {
	if filePath == "" {
		fmt.Print(data)
		return nil
	}
	f, err := os.OpenFile(filePath, os.O_RDWR, 0644)
	if err != nil {
		return err
	}
	defer f.Close()
	if err := f.Truncate(0); err != nil {
		return err
	}
	if _, err := f.Seek(0, 0); err != nil {
		return err
	}
	if _, err := f.WriteString(data); err != nil {
		return err
	}
	return nil
}

// cmdApplyDump implements `direnv apply_dump`
func cmdApplyDump(args []string) error {
	if len(args) < 1 {
		return fmt.Errorf("missing FILE argument")
	}
	data, err := os.ReadFile(args[0])
	if err != nil {
		return err
	}
	env, err := LoadEnvDump(strings.TrimSpace(string(data)))
	if err != nil {
		return err
	}
	sh := Detect("bash")
	for _, k := range env.Keys() {
		fmt.Print(sh.SetEnv(k, env[k]))
	}
	return nil
}

// cmdShowDump implements `direnv show_dump`
func cmdShowDump(args []string) error {
	if len(args) < 1 {
		return fmt.Errorf("missing DUMP argument")
	}
	env, err := LoadEnvDump(args[0])
	if err != nil {
		return err
	}
	data, err := jsonMarshalIndent(env)
	if err != nil {
		return err
	}
	fmt.Println(string(data))
	return nil
}

// cmdWatch implements `direnv watch`
func cmdWatch(args []string) error {
	if len(args) < 1 {
		return fmt.Errorf("unknown target shell '%s'", "")
	}
	sh := Detect(args[0])
	if sh == nil {
		return fmt.Errorf("unknown target shell '%s'", args[0])
	}
	w, err := ParseWatchesFromEnv()
	if err != nil {
		w = Watches{}
	}
	for _, p := range args[1:] {
		w = w.AddPath(p)
	}
	d, err := w.MarshalDump()
	if err != nil {
		return err
	}
	fmt.Print(sh.SetEnv("DIRENV_WATCHES", d))
	return nil
}

// cmdWatchDir implements `direnv watch-dir`
func cmdWatchDir(args []string) error {
	if len(args) < 1 {
		return fmt.Errorf("unknown target shell '%s'", "")
	}
	sh := Detect(args[0])
	if sh == nil {
		return fmt.Errorf("unknown target shell '%s'", args[0])
	}
	if len(args) < 2 {
		return fmt.Errorf("a directory is required to add to the list of watches")
	}
	w, err := ParseWatchesFromEnv()
	if err != nil {
		w = Watches{}
	}
	w = w.AddDir(args[1])
	d, err := w.MarshalDump()
	if err != nil {
		return err
	}
	fmt.Print(sh.SetEnv("DIRENV_WATCHES", d))
	return nil
}

// cmdWatchList implements `direnv watch-list`
func cmdWatchList(args []string) error {
	shellName := "bash"
	if len(args) > 0 {
		shellName = args[0]
	}
	sh := Detect(shellName)
	if sh == nil {
		return fmt.Errorf("unknown target shell '%s'", shellName)
	}
	w := Watches{}
	data, err := readAllStdin()
	if err != nil {
		return err
	}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		fields := strings.SplitN(line, " ", 2)
		if len(fields) != 2 {
			continue
		}
		var mod int64
		fmt.Sscanf(fields[0], "%d", &mod)
		w = append(w, Watch{Path: fields[1], ModTime: mod, Exists: true})
	}
	d, err := w.MarshalDump()
	if err != nil {
		return err
	}
	fmt.Print(sh.SetEnv("DIRENV_WATCHES", d))
	return nil
}

// cmdWatchPrint implements `direnv watch-print`
func cmdWatchPrint(args []string) error {
	null := false
	for _, a := range args {
		if a == "--null" || a == "-null" {
			null = true
		}
	}
	w, err := ParseWatchesFromEnv()
	if err != nil {
		w = Watches{}
	}
	sep := "\n"
	if null {
		sep = "\x00"
	}
	var b strings.Builder
	for _, x := range w {
		b.WriteString(x.Path)
		b.WriteString(sep)
	}
	fmt.Print(b.String())
	return nil
}

// cmdCurrent implements `direnv current`
func cmdCurrent(args []string) error {
	if len(args) < 1 {
		return fmt.Errorf("missing PATH argument")
	}
	w, err := ParseWatchesFromEnv()
	if err != nil {
		w = Watches{}
	}
	path, _ := filepath.Abs(args[0])
	for _, x := range w {
		if x.Path != path {
			continue
		}
		if x.IsStale() {
			return fmt.Errorf("File %q has changed", path)
		}
		return nil
	}
	return fmt.Errorf("File %q is unknown", path)
}

// cmdCheckRequired implements `direnv check-required`
func cmdCheckRequired(args []string) error {
	if len(args) < 1 {
		return fmt.Errorf("unknown target shell '%s'", "")
	}
	sh := Detect(args[0])
	if sh == nil {
		return fmt.Errorf("unknown target shell '%s'", args[0])
	}
	if len(args) < 3 {
		return fmt.Errorf("at least one file path is required")
	}
	envrc := args[1]
	paths := args[2:]
	out, err := checkRequiredImpl(sh, envrc, paths)
	if err != nil {
		return err
	}
	fmt.Print(out)
	return nil
}

// checkRequiredImpl renders the bash code for require_allowed
func checkRequiredImpl(sh Shell, envrc string, paths []string) (string, error) {
	w := Watches{}
	for _, p := range paths {
		w = w.AddPath(p)
	}
	var bad []string
	for _, p := range paths {
		rc := NewRC(p)
		if rc.Allowed != Allowed {
			bad = append(bad, p)
		}
	}
	watchDump, err := w.MarshalDump()
	if err != nil {
		return "", err
	}
	var b strings.Builder
	b.WriteString(sh.SetEnv("DIRENV_WATCHES", watchDump))
	if len(bad) > 0 {
		msg := ""
		if len(bad) == 1 {
			msg = fmt.Sprintf("%s requires approval. Run 'direnv allow' to approve.", bad[0])
		} else {
			msg = fmt.Sprintf("%s and %s require approval. Run 'direnv allow' to approve.",
				strings.Join(bad[:len(bad)-1], ", "), bad[len(bad)-1])
		}
		b.WriteString(sh.LogStatus(msg))
	}
	return b.String(), nil
}

// osProcess creates an os/exec Cmd for the given argv
func osProcess(argv []string) *exec.Cmd {
	c := exec.Command(argv[0], argv[1:]...)
	return c
}
