func (s *bashShellT) LogStatus(msg string) string {
	return fmt.Sprintf("log_error %s\n", bashQuote(msg))
}

func bashQuote(v string) string {
	return "$'" + bashEscape(v) + "'"
}

// LogStatusFor returns the shell-specific log_status rendering
func LogStatusFor(sh Shell, msg string) string {
	switch t := sh.(type) {
	case *bashShellT:
