package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

func readAllStdin() ([]byte, error) { return io.ReadAll(os.Stdin) }

// requiredDir returns the directory holding the required-file records for an
// envrc file.
func requiredDir(envrc string) string {
	return filepath.Join(config.DataDir, "allowed-required", hashKey(envrc))
}

// requiredPath returns the path of the record for a required file
func requiredPath(envrc, absPath string, contents []byte) string {
	h := sha256Hex(absPath + "\n")
	h2 := sha256.New()
	h2.Write([]byte(absPath + "\n"))
	h2.Write(contents)
	return filepath.Join(requiredDir(envrc), hexEncode(h2.Sum(nil)))
}

// allowRequiredFiles implements the DIRENV_REQUIRED part of `direnv allow`
func allowRequiredFiles(envrc string, required string) error {
	if required == "" {
		return nil
	}
	for _, rel := range strings.Split(required, ":") {
		abs := filepath.Join(filepath.Dir(envrc), rel)
		if !fileExists(abs) {
			return fmt.Errorf("required file does not exist: %s", rel)
		}
		fmt.Printf("direnv: allowing %s\n", rel)
		data, err := os.ReadFile(abs)
		if err != nil {
			return err
		}
		path := requiredPath(envrc, abs, data)
		if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
			return err
		}
		if err := os.WriteFile(path, []byte(rel+"\n"), 0644); err != nil {
			return err
		}
	}
	return nil
}

// cmdAllow2 is the full allow implementation including the required files
func allowAll(args []string) error {
	rc, err := rcFromArgs(args)
	if err != nil {
		return err
	}
	if err := rc.Allow(); err != nil {
		return err
	}
	return allowRequiredFiles(rc.Path, os.Getenv("DIRENV_REQUIRED"))
}
