package main

import (
	"fmt"
	"os"
	"regexp"
)

// ANSI colors used for the log output
const (
	colorRed   = "\033[31m"
	colorReset = "\033[0m"
)

// logFormat returns the printf format used for status messages
func logFormat() string {
	if !config.Loaded {
		return colorReset + "direnv: %s"
	}
	if config.LogFormat != "" {
		return config.LogFormat
	}
	return "direnv: %s"
}

// logFilterRe compiles the configured log filter
func logFilterRe() *regexp.Regexp {
	if config.LogFilter == "" {
		return nil
	}
	re, err := regexp.Compile(config.LogFilter)
	if err != nil {
		return nil
	}
	return re
}

// LogStatus logs a message to stderr with the standard direnv format.
func LogStatus(format string, args ...interface{}) {
	if config.Loaded && config.LogFormat == "-" {
		return
	}
	msg := fmt.Sprintf(format, args...)
	if re := logFilterRe(); re != nil && !re.MatchString(msg) {
		return
	}
	fmt.Fprintf(os.Stderr, logFormat()+"\n", msg)
}

// LogError logs an error to stderr with the standard direnv format.
func LogError(msg string) {
	fmt.Fprintln(os.Stderr, colorRed+"direnv: error "+msg+colorReset)
}

// LogErrorPlain logs an error without the "error" prefix.
func LogErrorPlain(msg string) {
	if config.Loaded {
		fmt.Fprintf(os.Stderr, "direnv: %s\n", msg)
		return
	}
	fmt.Fprintf(os.Stderr, colorRed+"direnv: "+msg+colorReset+"\n")
}
