cat > cmds5.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"strings"
)

// cmdDotenv implements `direnv dotenv`
func cmdDotenv(args []string) error {
	shellName := "bash"
	path := ""
	if len(args) > 0 {
		shellName = args[0]
	}
	if len(args) > 1 {
		path = args[1]
	}
	sh := Detect(shellName)
	if sh == nil {
		return fmt.Errorf("unknown target shell '%s'", shellName)
	}
	if path == "" {
		path = ".env"
	}
	if st, err := os.Stat(path); err == nil && st.IsDir() {
		path = joinPath(path, ".env")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	env, err := ParseDotenv(string(data))
	if err != nil {
		return err
	}
	var b strings.Builder
	for _, k := range env.Keys() {
		b.WriteString(sh.SetEnv(k, env[k]))
	}
	fmt.Print(b.String())
	return nil
}

// ParseDotenv parses a .env file into an environment
func ParseDotenv(data string) (Env, error) {
	env := Env{}
	for _, line := range strings.Split(data, "\n") {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		trimmed = strings.TrimPrefix(trimmed, "export ")
		trimmed = strings.TrimSpace(strings.TrimPrefix(strings.TrimPrefix(trimmed, "export"), "export"))
		trimmed = strings.TrimSpace(trimmed)
		i := strings.Index(trimmed, "=")
		if i < 0 {
			return nil, fmt.Errorf("invalid line: %s", line)
		}
		key := strings.TrimSpace(trimmed[:i])
		rest := strings.TrimSpace(trimmed[i+1:])
		var value string
		if rest == "" {
			value = ""
		} else if rest[0] == '"' || rest[0] == '\'' {
			quote := rest[0]
			end := -1
			for j := 1; j < len(rest); j++ {
				if rest[j] == '\\' && quote == '"' {
					j++
					continue
				}
				if rest[j] == quote {
					end = j
					break
				}
			}
			if end < 0 || (end+1 < len(rest) && strings.TrimSpace(rest[end+1:]) != "") {
				value = stripComment(rest)
				value = strings.Trim(value, `"'`)
			} else {
				value = rest[1:end]
				if quote == '"' {
					value = dotenvUnescape(value)
				}
			}
		} else {
			value = stripComment(rest)
		}
		env[key] = value
	}
	return env, nil
}

// stripComment removes a trailing comment from a dotenv value
func stripComment(v string) string {
	for i := 0; i < len(v); i++ {
		if v[i] == '#' {
			return strings.TrimSpace(v[:i])
		}
	}
	return strings.TrimSpace(v)
}

func dotenvUnescape(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			i++
			switch s[i] {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			default:
				b.WriteByte('\\')
				b.WriteByte(s[i])
			}
			continue
		}
		b.WriteByte(s[i])
	}
	return b.String()
}
GOEOF
