import sys,os,subprocess,re,json
ORIG='/workspace/executable'
MINE='/tmp/direnv-test'
def parse_env(out):
    env={}
    for m in re.finditer(r"export ([A-Za-z_][A-Za-z0-9_]*)=(\$?'((?:[^']|\\')*)'|[^;]*);", out):
        k=m.group(1); v=m.group(2)
        if v.startswith("$'"):
            body=m.group(3) or ''
            v=unescape(body)
        else:
            v=m.group(2)
        env[k]=v
    return env
def unescape(v):
    out=[];i=0
    while i<len(v):
        if v[i]=='\\' and i+1<len(v):
            c=v[i+1]
            if c=='x' and i+3<len(v):
                out.append(chr(int(v[i+2:i+4],16))); i+=4; continue
            mp={'n':'\n','t':'\t','r':'\r','\\':'\\',"'":"'"}
            out.append(mp.get(c,c)); i+=2; continue
        out.append(v[i]); i+=1
    return ''.join(out)
def run(binary,args,cwd,env=None):
    e=dict(os.environ)
    if env: e.update(env)
    return subprocess.run([binary]+args,capture_output=True,cwd=cwd,env=e)
def cmp(args,cwd,env=None,label=''):
    a=run(ORIG,args,cwd,env); b=run(MINE,args,cwd,env)
    ok=True
    if a.returncode!=b.returncode: ok=False
    ae=a.stdout.decode('utf8','replace'); be=b.stdout.decode('utf8','replace')
