{"command": "cd /workspace/src && cat > fetchurl.go <<'GOEOF'
package main

import (
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

// cmdFetchurl implements `direnv fetchurl`
func cmdFetchurl(args []string) error {
	if len(args) < 1 {
		return fmt.Errorf("missing URL argument")
	}
	url := args[0]
	var wantHash *SRI
	if len(args) > 1 {
		sri, err := ParseSRI(args[1])
		if err != nil {
			return err
		}
		wantHash = &sri
	}
	body, err := httpGet(url)
	if err != nil {
		return err
	}
	sum := sum256Bytes(body)
	got := SRI{Algo: "sha256", Hash: base64.StdEncoding.EncodeToString(sum)}
	if wantHash == nil {
		path, err := casWrite(got.String(), body)
		if err != nil {
			return err
		}
		fmt.Println(got.String())
		if isatty(os.Stdout) {
			fmt.Println()
			fmt.Println("Invoke fetchurl again with the hash as an argument to get the disk location:")
			fmt.Println()
			fmt.Printf("  direnv fetchurl %q %q\n", url, got.String())
			fmt.Printf("  #=> %s\n", path)
		}
		return nil
	}
	if wantHash.Algo != "sha256" {
		return fmt.Errorf("sri: unsupported algo %s", wantHash.Algo)
	}
	if wantHash.String() != got.String() {
		return fmt.Errorf("hash mismatch. Expected '%s' but got '%s'", wantHash.String(), got.String())
	}
	path, err := casWrite(got.String(), body)
	if err != nil {
		return err
	}
	fmt.Println(path)
	return nil
}

// SRI is a Subresource Integrity hash
type SRI struct {
	Algo string
	Hash string
}

// String renders the SRI hash
func (s SRI) String() string { return s.Algo + "-" + s.Hash }

// ParseSRI parses an SRI hash string
func ParseSRI(s string) (SRI, error) {
	i := strings.Index(s, "-")
	if i < 0 {
		return SRI{}, fmt.Errorf("sri: not a hash %s", s)
	}
	algo := s[:i]
	hashStr := s[i+1:]
	switch algo {
	case "sha256", "sha384", "sha512":
	default:
		return SRI{}, fmt.Errorf("sri: unsupported algo %s", algo)
	}
	if _, err := base64.StdEncoding.DecodeString(hashStr); err != nil {
		return SRI{}, err
	}
	return SRI{Algo: algo, Hash: hashStr}, nil
}

// casPathFor returns the on-disk location for a sha256 sum
func casPathFor(sum []byte) string {
	return filepath.Join(XDGCacheHome(), "direnv", "cas", hex.EncodeToString(sum))
}

// casWrite writes the content into the CAS, mimicking the original's temp file
// handling (including its warnings).
func casWrite(sri string, data []byte) (string, error) {
	sum := sum256Bytes(data)
	path := casPathFor(sum)
	if _, err := os.Stat(path); err == nil {
		return path, nil
	}
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return "", err
	}
	tmp, err := os.CreateTemp(dir, "tmp*")
	if err != nil {
		return "", err
	}
	name := tmp.Name()
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return "", err
	}
	if err := tmp.Chmod(0540); err != nil {
		tmp.Close()
		return "", err
	}
	if err := tmp.Close(); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to close temp file: %s\n", err)
	}
	if err := os.Rename(name, path); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to rename temp file %s: %s\n", name, err)
		return "", err
	}
	if err := tmp.Close(); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to close temp file: %s\n", err)
	}
	if err := os.Remove(name); err != nil {
		fmt.Fprintf(os.Stderr, "Warning: failed to remove temp file %s: %s\n", name, err)
	}
	return path, nil
}

// httpGet fetches a URL following redirects
func httpGet(url string) ([]byte, error) {
	client := &http.Client{}
	resp, err := client.Get(url)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("http GET failed for %s: %s", url, resp.Status)
	}
	return io.ReadAll(resp.Body)
}

func isatty(f *os.File) bool {
	st, err := f.Stat()
	if err != nil {
		return false
	}
	return st.Mode()&os.ModeCharDevice != 0
}
