d='/tmp/st5'
env={}
e=dict(os.environ)
p=subprocess.run(['/workspace/executable','export','bash'],capture_output=True,cwd=d,env=e)
env.update(parse_exports(p.stdout.decode()))
def t(label,extra):
    e=dict(os.environ); e.update(env)
    for k,v in extra.items():
        if v is None: e.pop(k,None)
        else: e[k]=v
    p=subprocess.run(['/workspace/executable','export','bash'],capture_output=True,cwd=d,env=e)
    print("%-30s log=%r keys=%r"%(label,p.stderr.decode().replace('\x1b','\\e').strip().replace('\n','|'),sorted(parse_exports(p.stdout.decode()))))
t('as-is',{})
t('DIRENV_REQUIRED unset',{'DIRENV_REQUIRED':None})
t('DIRENV_REQUIRED=pixi.toml',{'DIRENV_REQUIRED':'pixi.toml'})
t('DIRENV_REQUIRED=other',{'DIRENV_REQUIRED':'other'})
PY"}

