import sys,os,subprocess,shutil,time; sys.path.insert(0,'/tmp')
from hookcmp import runseq, ORIG
def fresh(d, files=None, allow=True):
    shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
    for n,c in (files or {}).items():
        p=os.path.join(d,n); os.makedirs(os.path.dirname(p),exist_ok=True)
        open(p,'w').write(c)
