fresh('/tmp/st5',{'.envrc':'require_allowed pixi.toml\nexport W=5\n','pixi.toml':'x\n'})
runseq(['/tmp/st5']*3, lambda: subprocess.run([ORIG,'allow'],cwd='/tmp/st5',capture_output=True), label='require_allowed')
PY"}

