{"command": "cd /tmp && python3 - <<'PY'
import sys,os,subprocess,json,re; sys.path.insert(0,'/tmp/h')
from hooksim import parse_exports,dec,parse_unsets
d='/tmp/st5'
env={}
for b in ['/workspace/executable','/tmp/direnv-test']:
    env={}
    for i in range(2):
        e=dict(os.environ); e.update(env)
        p=subprocess.run([b,'export','bash'],capture_output=True,cwd=d,env=e)
        ex=parse_exports(p.stdout.decode()); env.update(ex)
        if 'DIRENV_DIFF' in ex:
            dd=json.loads(dec(ex['DIRENV_DIFF']))
            print("%s run%d p=%r n=%r"%(b,i,json.dumps(dd['p'])[:80],json.dumps({k:(v[:25] if isinstance(v,str) else v) for k,v in dd['n'].items()})[:220]))
        else:
            print("%s run%d no diff exports"%([b][0][10:],i))
    print()
PY"}

